def _task(id, title="task", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
          due_at=None, tags=None, created_at=None):
    return Task(
        id=id, title=title, status=status, priority=priority,
        due_at=due_at, tags=tags or [],
        created_at=created_at or NOW - timedelta(hours=id),
    )


# ── TaskQuery validation ────────────────────────────────────────────────────

class TestTaskQuery:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    @pytest.mark.parametrize("field", ["created_at", "due_at", "priority", "title"])
    def test_valid_sort_fields(self, field):
        q = TaskQuery(sort=field)
        assert q.sort == field

    def test_invalid_sort_field(self):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort="invalid")

    @pytest.mark.parametrize("limit", [0, -1, 101, "abc"])
    def test_invalid_limit(self, limit):
        with pytest.raises(TaskQueryError):
            TaskQuery(limit=limit)

    def test_negative_offset(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(offset=-1)

    def test_tag_normalizes(self):
        q = TaskQuery(tag="  MyTag  ")
        assert q.tag == "mytag"

    def test_tag_invalid_raises(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_search_strips_whitespace(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"

    def test_search_blank_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None


# ── TaskPage.has_more ────────────────────────────────────────────────────────

class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[_task(1)], total=5, limit=2, offset=0)
        assert page.has_more is True

    def test_has_more_false_at_end(self):
        page = TaskPage(items=[_task(1)], total=1, limit=10, offset=0)
        assert page.has_more is False

    def test_has_more_false_with_offset(self):
