                  created_at=NOW - timedelta(hours=3),
                  due_at=NOW + timedelta(days=1)),
            _task(2, "Apple", priority=TaskPriority.HIGH,
                  created_at=NOW - timedelta(hours=1),
                  due_at=NOW + timedelta(days=5)),
            _task(3, "Mango", priority=TaskPriority.MEDIUM,
                  created_at=NOW - timedelta(hours=2)),  # no due_at
        ]

