        page = apply_query(tasks, TaskQuery(limit=5, offset=8), NOW)
        assert len(page.items) == 2
        assert page.has_more is False

    def test_offset_beyond_total(self, tasks):
        page = apply_query(tasks, TaskQuery(offset=100), NOW)
        assert len(page.items) == 0
        assert page.total == 10
        assert page.has_more is False

    def test_full_page_no_more(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=100), NOW)
        assert len(page.items) == 10
        assert page.has_more is False

