class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def _make_task(self, id: int, title: str = "task") -> Task:
        return Task(id=id, title=title)

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3

    def test_add_and_get(self, repo):
        task = self._make_task(1, "Buy milk")
        repo.add(task)
        retrieved = repo.get(1)
        assert retrieved is not None
        assert retrieved.title == "Buy milk"

    def test_add_duplicate_id_raises(self, repo):
        repo.add(self._make_task(1))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(self._make_task(1))

    def test_get_nonexistent_returns_none(self, repo):
        assert repo.get(999) is None

    def test_list_returns_all(self, repo):
        repo.add(self._make_task(1, "A"))
        repo.add(self._make_task(2, "B"))
        tasks = list(repo.list())
        assert len(tasks) == 2

    def test_list_returns_snapshot(self, repo):
        repo.add(self._make_task(1))
        first_list = repo.list()
        # Mutating the returned list doesn't affect the repo
        assert isinstance(first_list, list)

    def test_update_existing(self, repo):
        task = self._make_task(1, "Original")
        repo.add(task)
        task.title = "Updated"
        repo.update(task)
        assert repo.get(1).title == "Updated"

    def test_update_nonexistent_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(self._make_task(999))

    def test_delete_existing_returns_true(self, repo):
        repo.add(self._make_task(1))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_nonexistent_returns_false(self, repo):
        assert repo.delete(999) is False


class TestNormalizeTags:
    def test_deduplicates_by_name(self):
        result = normalize_tags([Tag("python"), Tag("PYTHON"), Tag("Python")])
        assert len(result) == 1
        assert result[0].name == "python"

    def test_preserves_first_seen_order(self):
        result = normalize_tags([Tag("beta"), Tag("alpha"), Tag("beta")])
        assert [t.name for t in result] == ["beta", "alpha"]

    def test_accepts_strings(self):
        result = normalize_tags(["hello", "WORLD"])
        assert [t.name for t in result] == ["hello", "world"]

    def test_mixed_tag_and_string(self):
        result = normalize_tags([Tag("a"), "B", Tag("a")])
        assert [t.name for t in result] == ["a", "b"]

    def test_empty_iterable(self):
        assert normalize_tags([]) == []

